void TellicoModelTest::testEntryModel() {
  Tellico::Data::CollPtr coll(new Tellico::Data::BookCollection(true)); // add default fields
  Tellico::Data::EntryPtr entry1(new Tellico::Data::Entry(coll));
  entry1->setField(QStringLiteral("title"), QStringLiteral("Star Wars"));
  const QUrl u = QUrl::fromLocalFile(QFINDTESTDATA("../../icons/128-apps-tellico.png"));
  const QString imageId = Tellico::ImageFactory::addImage(u);
  entry1->setField(QStringLiteral("cover"), imageId);
  coll->addEntries(entry1);

  Tellico::EntryModel entryModel(this);
  ModelTest test1(&entryModel);

  Tellico::EntryIconModel iconModel(this);
  ModelTest test2(&iconModel);

  TestEntrySortModel sortModel(this);
  ModelTest test3(&sortModel);

  iconModel.setSourceModel(&entryModel);
  sortModel.setSourceModel(&entryModel);

  entryModel.setFields(coll->fields());
  entryModel.setEntries(coll->entries());
  QCOMPARE(entryModel.index(0, 0), entryModel.indexFromEntry(entry1));

  Tellico::Data::FieldPtr field1(new Tellico::Data::Field(QStringLiteral("test"), QStringLiteral("test")));
  coll->addField(field1);
  entryModel.setFields(coll->fields());

  Tellico::Data::EntryPtr entry2(new Tellico::Data::Entry(coll));
  coll->addEntries(entry2);
  entryModel.addEntries(Tellico::Data::EntryList() << entry2);

  Tellico::Data::FieldPtr field2(new Tellico::Data::Field(QStringLiteral("test2"), QStringLiteral("test2")));
  coll->addField(field2);
  entryModel.addFields(Tellico::Data::FieldList() << field2);

  // Check FieldPtrRole in model data
  QModelIndex index = entryModel.index(0, entryModel.columnCount()-1);
  QVERIFY(index.isValid());
  QCOMPARE(entryModel.data(index, Tellico::FieldPtrRole),
           QVariant::fromValue(field2));
  //check FieldPtrRole in header model data
  QCOMPARE(entryModel.headerData(entryModel.columnCount()-1, Qt::Horizontal, Tellico::FieldPtrRole),
           QVariant::fromValue(field2));

  sortModel.setSortColumn(0);
  sortModel.setSecondarySortColumn(1);
  sortModel.setTertiarySortColumn(2);
  QCOMPARE(sortModel.sortColumn(), 0);
  QCOMPARE(sortModel.secondarySortColumn(), 1);
  QCOMPARE(sortModel.tertiarySortColumn(), 2);
  sortModel.sort(0, Qt::DescendingOrder);
  QVERIFY(!sortModel.lessThan(index, index));
  sortModel.setSortRole(Tellico::RowCountRole);
  sortModel.sort(0, Qt::DescendingOrder);
  QVERIFY(!sortModel.lessThan(index, index));
  sortModel.setSortRole(Tellico::EntryPtrRole);
  sortModel.sort(0);
  QVERIFY(!sortModel.lessThan(index, index));

  QVariant icon1 = iconModel.data(iconModel.index(0, 0), Qt::DecorationRole);
  QVERIFY(icon1.isValid());
  QVERIFY(!icon1.isNull());
  QVERIFY(icon1.canConvert<QIcon>());

  entry2->setField(QStringLiteral("cover"), imageId);
  entryModel.modifyEntries({entry2});
  auto icon2 = iconModel.data(iconModel.index(1, 0), Qt::DecorationRole).value<QIcon>();
  QVERIFY(!icon2.isNull());

  entry2->setField(QStringLiteral("title"), QStringLiteral("Modified"));
  entryModel.modifyEntries({entry2}); // marks row 1 dirty
  entryModel.removeEntries({entry1}); // entry2 moves to row 0

  auto movedIcon = iconModel.data(iconModel.index(0, 0), Qt::DecorationRole).value<QIcon>();
  QVERIFY(!movedIcon.isNull());
  QVERIFY(icon2.cacheKey() != movedIcon.cacheKey()); // movedIcon is the default instead of from the cache

  Tellico::FilterRule* rule1 = new Tellico::FilterRule(QStringLiteral("title"),
                                                       QStringLiteral("Star Wars"),
                                                       Tellico::FilterRule::FuncEquals);
  Tellico::FilterPtr filter(new Tellico::Filter(Tellico::Filter::MatchAny));
  filter->append(rule1);

  sortModel.setFilter(filter);

  entryModel.clear();
  entryModel.setFields(coll->fields());
  entryModel.setEntries(coll->entries());
  QCOMPARE(entryModel.index(0, 0), entryModel.indexFromEntry(entry1));

  Tellico::Data::FieldPtr field3(new Tellico::Data::Field(QStringLiteral("test"), QStringLiteral("test-new")));
  coll->modifyField(field3); // same field name as previous
  QCOMPARE(coll->fields().count(), entryModel.columnCount(QModelIndex()));
  entryModel.modifyField(field1, field3);

  coll->removeField(field3);
  entryModel.removeFields(Tellico::Data::FieldList() << field3);
  QCOMPARE(coll->fields().count(), entryModel.columnCount(QModelIndex()));

  auto fields = coll->fields();
  QVERIFY(fields.count() > 2);
  Tellico::Data::FieldList newFields;
  newFields << fields.at(1) << fields.at(0) << fields.sliced(2);
  coll->reorderFields(newFields);
  entryModel.reorderFields(newFields);

  QCOMPARE(coll->entries().count(), entryModel.rowCount(QModelIndex()));
  coll->removeEntries(Tellico::Data::EntryList() << entry2);
  QCOMPARE(coll->entries().count() + 1, entryModel.rowCount(QModelIndex()));
  entryModel.removeEntries(Tellico::Data::EntryList() << entry2);
  QCOMPARE(coll->entries().count(), entryModel.rowCount(QModelIndex()));

  for(Tellico::ModelIterator eIt(&entryModel); eIt.entry(); ++eIt) {
    QVERIFY(eIt.isValid());
  }

  // check valid SaveStateRole
  index = entryModel.index(0, entryModel.columnCount()-1);
  entryModel.setData(index, Tellico::ModifiedState, Tellico::SaveStateRole);
  entryModel.clearSaveState();

  // save state should follow an entry when preceding rows are removed
  entryModel.addEntries({entry2});
  index = entryModel.indexFromEntry(entry2);
  entryModel.setData(index, Tellico::ModifiedState, Tellico::SaveStateRole);
  QCOMPARE(entryModel.data(index, Tellico::SaveStateRole), Tellico::ModifiedState);
  entryModel.removeEntries({entry1});
  index = entryModel.indexFromEntry(entry2);
  QCOMPARE(entryModel.data(index, Tellico::SaveStateRole), Tellico::ModifiedState);

  entryModel.addEntries({});
}

void TellicoModelTest::testEntryModelImageRequest() {
  QUrl imgUrl = QUrl::fromLocalFile(QFINDTESTDATA("../../icons/tellico.png"));
  imgUrl = imgUrl.adjusted(QUrl::NormalizePathSegments);
  const QString imageId = imgUrl.url();

  QFile f(QFINDTESTDATA("/data/image_link_test.xml"));
  QVERIFY(f.exists());
  QVERIFY(f.open(QIODevice::ReadOnly | QIODevice::Text));

  QTextStream in(&f);
  QString fileText = in.readAll();
  fileText.replace(QLatin1String("%COVER%"), imageId);

  Tellico::Import::TellicoImporter importer(fileText);
  Tellico::Data::CollPtr coll = importer.collection();
  QVERIFY(coll);
  QCOMPARE(coll->entries().count(), 1);

  Tellico::Data::EntryPtr entry = coll->entries().at(0);
  QVERIFY(entry);
  QCOMPARE(entry->field(QStringLiteral("cover")), imageId);

  Tellico::EntryModel entryModel(this);
  QVERIFY(entryModel.m_requestedImages.isEmpty());
  ModelTest test1(&entryModel);

  entryModel.setFields(coll->fields());
  entryModel.setEntries(coll->entries());
  QVERIFY(entryModel.m_requestedImages.isEmpty());

  QSignalSpy spy(Tellico::ImageFactory::self(), &Tellico::ImageFactory::imageRequestFinished);
  QModelIndex index = entryModel.index(0, 0);

  auto pixfromVar1 = entryModel.data(index, Tellico::PrimaryImageRole).value<QPixmap>();
  QVERIFY(!entryModel.m_requestedImages.isEmpty()); // pending image request
  QVERIFY(!pixfromVar1.isNull()); // default pixmap
  QVERIFY(spy.wait(2000));
  QVERIFY(entryModel.m_requestedImages.isEmpty());

  auto pixfromVar2 = entryModel.data(index, Tellico::PrimaryImageRole).value<QPixmap>();
  QVERIFY(pixfromVar1.cacheKey() != pixfromVar2.cacheKey()); // different image

  auto pix = Tellico::ImageFactory::pixmap(imageId, Tellico::MAX_ENTRY_ICON_SIZE,
                                           Tellico::MAX_ENTRY_ICON_SIZE);
  QVERIFY(pixfromVar1.cacheKey() != pix.cacheKey()); // different image
  QVERIFY(pixfromVar2.cacheKey() == pix.cacheKey()); // same image

  Tellico::Data::EntryPtr entry2(new Tellico::Data::Entry(coll));
  entry2->setField(QStringLiteral("title"), QStringLiteral("Star Wars"));
  coll->addEntries(entry2);
  entryModel.addEntries({entry2});

  // now remove the image from the cache, but not from the pixmap cache
  Tellico::ImageFactory::removeImage(imageId, false);
  entryModel.modifyEntries({entry});

  index = entryModel.index(0, 0);
  auto pixfromVar3 = entryModel.data(index, Tellico::PrimaryImageRole).value<QPixmap>();
  QVERIFY(entryModel.m_requestedImages.isEmpty()); // no request since still in cache
  QVERIFY(pixfromVar2.cacheKey() == pixfromVar3.cacheKey()); // same default image

  entry2->setField(QStringLiteral("cover"), QStringLiteral("https://example.com"));
  entryModel.modifyEntries({entry2});

  QModelIndex index2 = entryModel.index(1, 0);
  QVERIFY(index2.isValid());
  auto noPix = entryModel.data(index2, Tellico::PrimaryImageRole).value<QPixmap>();
  Q_UNUSED(noPix);
  QVERIFY(!entryModel.m_requestedImages.isEmpty()); // pending image request
  QVERIFY(spy.wait(2000));
  QVERIFY(entryModel.m_requestedImages.isEmpty()); // failed request still removes it from request list
}

void TellicoModelTest::testEntryModelFailedImageRequest() {
  const QString imageId = QStringLiteral("https://tellico-project.org/nonexistent-image-for-test");

  Tellico::Data::CollPtr coll(new Tellico::Data::BookCollection(true));
  Tellico::Data::EntryPtr entry(new Tellico::Data::Entry(coll));
  entry->setField(QStringLiteral("title"), QStringLiteral("Test Book"));
  entry->setField(QStringLiteral("cover"), imageId);
  coll->addEntries(entry);

  QCOMPARE(coll->entries().count(), 1);
  QCOMPARE(entry->field(QStringLiteral("cover")), imageId);

  // Make an initial request to mark the failed-image state in ImageFactory
  // Ensure the failure is completed before moving on
  QSignalSpy imageSpy(Tellico::ImageFactory::self(),
                      &Tellico::ImageFactory::imageRequestFinished);
  Tellico::ImageFactory::requestImageById(imageId);

  if(imageSpy.isEmpty()) {
    QVERIFY(imageSpy.wait(5000));
  }

  QCOMPARE(imageSpy.last().at(0).toString(), imageId);
  QCOMPARE(imageSpy.last().at(1).toBool(), false);

  Tellico::EntryModel entryModel(this);
  QVERIFY(entryModel.m_requestedImages.isEmpty());
  ModelTest test1(&entryModel);

  entryModel.setFields(coll->fields());
  entryModel.setEntries(coll->entries());
  QVERIFY(entryModel.m_requestedImages.isEmpty());

  // Find the column corresponding to the cover image field
  int imageColumn = -1;
  for(int col = 0; col < entryModel.columnCount(); ++col) {
    if(entryModel.field(entryModel.index(0, col))->name() == QLatin1String("cover")) {
      imageColumn = col;
      break;
    }
  }
  QVERIFY(imageColumn >= 0);

  const QModelIndex index = entryModel.index(0, imageColumn);
  QVERIFY(index.isValid());

  int depth = 0;
  int maxDepth = 0;

  // Mimic QListView re-reading the decoration whenever
  // the model reports that the data changed.
  // https://bugs.kde.org/show_bug.cgi?id=526952
  const auto conn = connect(&entryModel, &QAbstractItemModel::dataChanged,
                                  this, [&](const QModelIndex& topLeft,
                                            const QModelIndex& bottomRight,
                                            const QList<int>&) {
    if(index.row() < topLeft.row() ||
       index.row() > bottomRight.row() ||
       index.column() < topLeft.column() ||
       index.column() > bottomRight.column()) {
      return;
    }

    ++depth;
    maxDepth = qMax(maxDepth, depth);
    // Prevent stack overflow in the broken implementation
    if(depth < 5) {
      entryModel.data(index, Qt::DecorationRole);
    }
    --depth;
  });

  // trigger the initial image request
  QSignalSpy spy(&entryModel, &QAbstractItemModel::dataChanged);
  entryModel.data(index, Qt::DecorationRole);
  disconnect(conn);

  QVERIFY2(maxDepth <= 1, "Failed image request caused recursive dataChanged()");
  QCOMPARE(spy.count(), 0);
}

void TellicoModelTest::testFilterModel() {
  Tellico::FilterModel filterModel(this);
  ModelTest test1(&filterModel);

  Tellico::FilterRule* rule1 = new Tellico::FilterRule(QStringLiteral("title"),
                                                       QStringLiteral("Star Wars"),
                                                       Tellico::FilterRule::FuncEquals);
  Tellico::FilterPtr filter(new Tellico::Filter(Tellico::Filter::MatchAny));
  filter->append(rule1);
  filterModel.addFilter(filter);

  Tellico::Data::CollPtr c = Tellico::Data::Document::self()->collection();
  Tellico::Data::EntryPtr entry1(new Tellico::Data::Entry(c));
  entry1->setField(QStringLiteral("title"), QStringLiteral("Star Wars"));
  c->addEntries(entry1);

  filterModel.clear();
  filterModel.addFilter(filter);
  QModelIndex filterIndex = filterModel.index(0, 0);
  QVERIFY(filterIndex.isValid());
  QCOMPARE(filter, filterModel.filter(filterIndex));
  QVERIFY(filterModel.indexContainsEntry(filterIndex, entry1));

  filterModel.invalidate(filterIndex);
  filterIndex = filterModel.index(0, 0);
  QVERIFY(filterIndex.isValid());
  QCOMPARE(filter, filterModel.filter(filterIndex));
  QModelIndex entryIndex = filterModel.index(0, 0, filterIndex);
  QVERIFY(entryIndex.isValid());
  QCOMPARE(entry1, filterModel.entry(entryIndex));
  QVERIFY(filterModel.indexContainsEntry(filterIndex, entry1));

  QVERIFY(filterModel.setHeaderData(0, Qt::Horizontal, QStringLiteral("New Value")));
  QCOMPARE(filterModel.data(entryIndex, Qt::DisplayRole).toString(), entry1->title());
  QCOMPARE(filterModel.data(entryIndex, Tellico::EntryPtrRole).value<Tellico::Data::EntryPtr>(), entry1);
  QCOMPARE(filterModel.data(entryIndex, Tellico::RowCountRole), filterModel.rowCount(entryIndex));

  // invalidate a filter with no matching entries
  entry1->setField(QStringLiteral("title"), QStringLiteral("Empire Strikes Back"));
  filterModel.invalidate(filterIndex);
  QCOMPARE(filterModel.rowCount(filterIndex), 0);
  // and invalidate again when it already has no children
  filterModel.invalidate(filterIndex);
  QCOMPARE(filterModel.rowCount(filterIndex), 0);

  filterModel.removeFilter(filter);

  filterModel.addFilters({});
}

void TellicoModelTest::testGroupModel() {
  Tellico::Data::CollPtr coll(new Tellico::Data::BookCollection(true)); // add default fields
  Tellico::Data::EntryPtr entry1(new Tellico::Data::Entry(coll));
  entry1->setField(QStringLiteral("title"), QStringLiteral("Star Wars"));
  entry1->setField(QStringLiteral("author"), QStringLiteral("George Lucas"));
  coll->addEntries(entry1);
  Tellico::Data::EntryPtr entry2(new Tellico::Data::Entry(coll));
  entry2->setField(QStringLiteral("title"), QStringLiteral("Empire Strikes Back"));
  entry2->setField(QStringLiteral("author"), QStringLiteral("George Lucas"));
  coll->addEntries(entry2);
  Tellico::Data::EntryPtr entry3(new Tellico::Data::Entry(coll));
  entry3->setField(QStringLiteral("title"), QStringLiteral("1632"));
  entry3->setField(QStringLiteral("author"), QStringLiteral("Eric Flint"));
  coll->addEntries(entry3);

  Tellico::EntryGroupModel groupModel(this);
  ModelTest test1(&groupModel);

  TestGroupSortModel sortModel(this);
  ModelTest test2(&sortModel);

  sortModel.setSourceModel(&groupModel);

  Tellico::Data::EntryGroup emptyGroup(QString(), QStringLiteral("author"));
  groupModel.addGroup(&emptyGroup);

  Tellico::Data::EntryGroupDict* dict = coll->entryGroupDictByName(QStringLiteral("author"));
  groupModel.addGroups(dict->values(), QString());
  QCOMPARE(sortModel.rowCount(), 3);

  sortModel.setEntrySortField(QStringLiteral("title"));
  QCOMPARE(sortModel.entrySortField(), QLatin1String("title"));
  groupModel.removeGroup(&emptyGroup);
  QCOMPARE(sortModel.rowCount(), 2);

  sortModel.sort(0, Qt::AscendingOrder);
  auto index1 = sortModel.index(0, 0);
  auto sortEntry = sortModel.index(0, 0, index1).data(Tellico::EntryPtrRole)
                                                .value<Tellico::Data::EntryPtr>();
  QVERIFY(sortEntry);
  // sorted in this order, the first entry in the first group should be entry3
  QCOMPARE(sortEntry->id(), entry3->id());

  sortModel.sort(0);
  sortModel.setEntrySortField(QStringLiteral("author"));
  QCOMPARE(sortModel.entrySortField(), QLatin1String("author"));
  sortModel.sort(0, Qt::DescendingOrder);
  auto groupIndex = groupModel.index(0, 0);
  auto entryIndex = groupModel.index(0, 0, groupIndex);
  QVERIFY(entryIndex.isValid());
  QVERIFY(!sortModel.lessThan(groupIndex, groupIndex));
  QVERIFY(!sortModel.lessThan(entryIndex, entryIndex));

  sortModel.sort(0, Qt::AscendingOrder);
  QVERIFY(!sortModel.lessThan(groupIndex, groupIndex));
  QVERIFY(!sortModel.lessThan(entryIndex, entryIndex));

  Tellico::ModelIterator gIt(&sortModel);
  QVERIFY(gIt.isValid());
  auto group = gIt.group();
  QVERIFY(group);
  QCOMPARE(group->groupName(), QStringLiteral("Flint, Eric"));
  QCOMPARE(group->fieldName(), QStringLiteral("author"));
  QCOMPARE(group->size(), 1);
  QVERIFY(!group->hasEmptyGroupName());
  QVERIFY(!group->emptyGroupName().isEmpty());
  groupIndex = groupModel.indexFromGroup(group);
  QVERIFY(groupIndex.isValid());
  QCOMPARE(groupModel.modifyGroup(group), groupIndex);
  QCOMPARE(groupModel.data(groupIndex, Tellico::RowCountRole), groupModel.rowCount(groupIndex));
  QVERIFY(!sortModel.lessThan(groupIndex, groupIndex));

  group->clear();
  groupModel.modifyGroup(group); // invalid 0,-1 insert
  groupModel.modifyGroup(group); // also invalid 0,-1 remove
  QCOMPARE(groupModel.rowCount(groupIndex), 0);

  ++gIt;
  QVERIFY(gIt.isValid());
  group = gIt.group();
  QVERIFY(group);
  QCOMPARE(group->groupName(), QStringLiteral("Lucas, George"));
  QCOMPARE(group->fieldName(), QStringLiteral("author"));
  QCOMPARE(group->size(), 2);
  QVERIFY(!group->hasEmptyGroupName());

  ++gIt;
  QVERIFY(!gIt.group());

  groupModel.removeGroup(group);
  QCOMPARE(groupModel.rowCount(), 1);

  groupModel.clear();
  QCOMPARE(groupModel.rowCount(), 0);

  groupModel.addGroups({}, QString());
}

void TellicoModelTest::testSelectionModel() {
  qRegisterMetaType<Tellico::Data::EntryList>("Tellico::Data::EntryList");
  // this mimics the model dependencies used in mainwindow.cpp
  Tellico::EntryModel entryModel(this);
  ModelTest test1(&entryModel);
  Tellico::EntryIconModel iconModel(this);
  ModelTest test2(&iconModel);
  iconModel.setSourceModel(&entryModel);

  QItemSelectionModel selModel(&entryModel, this);
  Tellico::EntrySelectionModel proxySelect(&iconModel, &selModel, this);

  Tellico::Data::CollPtr coll(new Tellico::Data::Collection(true)); // add default fields
  Tellico::Data::EntryPtr entry1(new Tellico::Data::Entry(coll));
  entry1->setField(QStringLiteral("title"), QStringLiteral("Test1"));
  coll->addEntries(entry1);

  entryModel.setFields(coll->fields());
  entryModel.setEntries(coll->entries());

  QSignalSpy entriesSelectedSpy(&proxySelect, SIGNAL(entriesSelected(Tellico::Data::EntryList)));
  selModel.select(entryModel.index(0,0), QItemSelectionModel::Select);
  QCOMPARE(entriesSelectedSpy.count(), 1);

  Tellico::Data::EntryList entries = proxySelect.selectedEntries();
  QCOMPARE(entries.count(), 1);
  QCOMPARE(entries.at(0)->title(), QStringLiteral("Test1"));

  Tellico::Data::EntryPtr entry2(new Tellico::Data::Entry(coll));
  entry2->setField(QStringLiteral("title"), QStringLiteral("test2"));
  coll->addEntries(entry2);
  entryModel.addEntries(Tellico::Data::EntryList() << entry2);

  auto icon = iconModel.data(iconModel.index(0, 0), Qt::DecorationRole);
  QVERIFY(icon.canConvert<QIcon>());
  QVERIFY(!icon.value<QIcon>().isNull());

  entries = proxySelect.selectedEntries();
  QCOMPARE(entries.count(), 1);
  QCOMPARE(entries.at(0)->title(), QStringLiteral("Test1"));

  selModel.select(entryModel.index(1,0), QItemSelectionModel::Select);
  entries = proxySelect.selectedEntries();
  QCOMPARE(entries.count(), 2);
  QCOMPARE(entries.at(0)->title(), QStringLiteral("Test1"));
  QCOMPARE(entries.at(1)->title(), QStringLiteral("Test2"));

  selModel.select(entryModel.index(0,0), QItemSelectionModel::Toggle);
  entries = proxySelect.selectedEntries();
  QCOMPARE(entries.count(), 1);
  QCOMPARE(entries.at(0)->title(), QStringLiteral("Test2"));

  entryModel.clear();
  // now there should be no selection since EntryModel::clear calls modelReset()
  // and the proxy selection is connected to that signal
  entries = proxySelect.selectedEntries();
  QCOMPARE(entries.count(), 0);
}

